                        <div class="bao-time-bts" :class="tdas == 2 ? 'active' : ''" @click="yesterday">昨天</div>
                        <div class="bao-time-bts" :class="tdas == 3 ? 'active' : ''" @click="thisWeek">本星期</div>
                        <div class="bao-time-bts" :class="tdas == 4 ? 'active' : ''" @click="prevWeek">上星期</div>
                        <div class="bao-time-bts" :class="tdas == 5 ? 'active' : ''" @click="thisMonth">本月</div>
                        <div class="bao-time-bts" :class="tdas == 6 ? 'active' : ''" @click="prevMonth">上月</div>
                    </div>
                    <div class="bzkj">
                        <div class="bzkj-t" @click="twoNext">本周<br>快捷</div>
                    </div>
                </div>
            </div>
            <div class="ctable">
                <table>
                    <tbody>
                        <tr>
                            <td colspan="2">
                                <div class="footerbtn" style="justify-content:start;margin-top:10px;">
                                    <div class="xzall" :class="yxtp == 1 ? 'active' : ''" @click="selectAll">全选</div>
                                    <div class="xzall" :class="yxtp == 2 ? 'active' : ''" @click="cancelAll">全不选</div>
                                </div>
                                <van-checkbox-group v-model="params.lotteryList" @change="getLotteryList"
                                    style="display:flex;flex-wrap:wrap;">
                                    <van-checkbox v-for="item in gameTypeList" :key="item.id" :name="item.id"
                                        style="margin-bottom: 10px;width:160px;" icon-size="16px" shape="square">{{ item.name }}
                                    </van-checkbox>
                                </van-checkbox-group>
                            </td>
                        </tr>
                        <tr v-if="params.lotteryList.length == 1 && isTodayOrYesterday">
                            <td class="lefts">期数</td>
                            <td>
                                <div>
                                    <select v-model="params.period" placeholder="请选择彩种">
                                        <option v-for="(item, index) in options" :key="index + 1" :value="item.issue">
                                            {{ item.name }}
                                        </option>
                                    </select>
                                </div>
                            </td>
                        </tr>
                        <tr>
                            <td class="lefts">报表种类</td>
                            <td>
                                <div>
                                    <van-radio-group direction="horizontal" v-model="params.type" @change="flbb">
                                        <van-radio name="1" style="margin-right:6px" icon-size="16px">交收报表</van-radio>
                                        <van-radio name="2" style="margin-right:6px" icon-size="16px">分类报表</van-radio>
                                    </van-radio-group>
                                </div>
                            </td>
                        </tr>
                        <tr>
                            <td class="lefts">结算状态</td>
                            <td>
                                <div>
                                    <van-radio-group direction="horizontal" v-model="params.status">
                                        <van-radio :name="2" style="margin-right:6px" icon-size="16px">已结算</van-radio>
                                        <van-radio :name="1" style="margin-right:6px" icon-size="16px">未结算</van-radio>
                                    </van-radio-group>
                                </div>
                            </td>
                        </tr>
                        <tr>
                            <td class="lefts">下注人数</td>
                            <td>
                                <div>
                                    <van-radio-group direction="horizontal" v-model="params.playCountType">
                                        <van-radio :name="1" style="margin-right:6px" icon-size="16px">是</van-radio>
                                        <van-radio :name="0" style="margin-right:6px" icon-size="16px">否</van-radio>
                                    </van-radio-group>
                                </div>
                            </td>
                        </tr>
                        <tr v-if="params.type == 1">
                            <td class="lefts">用户名</td>
                            <td>
                                <van-field v-model="params.account" style="width:160px" class="input" size="mini"></van-field>
                            </td>
                        </tr>
                        <tr v-if="params.type == 1">
                            <td class="lefts">下注金额</td>
                            <td>
                                <van-field v-model="params.credit" type="number" style="width:160px" class="input"
                                    size="mini"></van-field>
                            </td>
                        </tr>
                        <tr v-if="params.type == 1">
                            <td class="lefts">盈亏金额</td>
                            <td>
                                <van-field v-model="params.win" style="width:160px"
                                    @keyup.native="params.win = params.win.replace(/^(0+)|[^-/\d]+/g, '')" class="input"
                                    size="mini"></van-field>
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
            <div style="font-size:12px;color: #f84243;text-align:center;padding:10px 0">备注：6AM-7AM系统维护时间,会影响报表导出功能,敬请谅解</div>
            <div class="footerbtn">
                <div class="subcanl" @click="$router.back(-1)">取消</div>
                <div class="submits" @click="reportQuery">确定</div>
            </div>
        </div>
        <!-- Vant4 日期选择器 -->
        <van-popup v-model:show="showStart" position="bottom">
            <van-date-picker :model-value="dtime" @confirm="val => confirmTime(val, 'start')"
                @cancel="showStart = false" />
        </van-popup>
        <van-popup v-model:show="showEnd" position="bottom">
            <van-date-picker :model-value="dtime1"  @confirm="val => confirmTime(val, 'end')"
                @cancel="showEnd = false" />
        </van-popup>
