<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'
import { useTimeUtils } from '@/utils/time'
const userTime = useTimeUtils();

// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()
const tits = ref("报表查询")
const num = ref(3)
// 设置日期范围（可选）
const minDate = ref(new Date(2020, 0, 1))
const maxDate = ref(new Date())

// --- 数据定义 ---
const dtime = ref([])
const dtime1 = ref([])
const showStart = ref(false)
const showEnd = ref(false)
const isTodayOrYesterday = ref(true)
const times = ref('')
const currentDate = ref(new Date())
const options = ref([])
const gameTypeList = ref([])
const tdas = ref(1)
const yxtp = ref(1)

const params = reactive({
    start: '',
    end: '',
    accountId: '',
    lotteryList: [],
    type: '1',
    status: 2,
    account: '',
    credit: '',
    win: '',
    period: '',
    playCountType: 0,
})
// 初始化当前日期数组
const initCurrentDateArray = (obj) => {
    const date = new Date(obj)
    dtime.value = [date.getFullYear(), date.getMonth() + 1, date.getDate()]
    dtime1.value = [date.getFullYear(), date.getMonth() + 1, date.getDate()]
}
// --- 方法定义 ---
const formatTime = (date) => {
    const year = date.getFullYear()
    const month = (date.getMonth() + 1) < 10 ? '0' + (date.getMonth() + 1) : (date.getMonth() + 1)
    const day = date.getDate() < 10 ? '0' + date.getDate() : date.getDate()
    return `${year}-${month}-${day}`
}

const getRunDate = async() => {
    try {
        const res = await userStore.getDate()
        times.value = res.data
        initCurrentDateArray(res.data)
        toDay()
    } catch (error) {
        console.error('获取跑批时间失败:', error)
    }
}

const twoNext = () => {
    router.push({ path: `/twoWeek` })
}

const flbb = () => {
    params.account = ''
    params.win = ''
    params.credit = ''
}

const confirmTime = (val, field) => {
    params[field] = val.selectedValues[0]+'-'+val.selectedValues[1]+'-'+val.selectedValues[2]
    if (field === 'start'){
      showStart.value = false
      dtime.value = val.selectedValues
    }else{
      showEnd.value = false
      dtime1.value = val.selectedValues
    } 
}

const toDay = () => {
    tdas.value = 1
    const start = new Date(times.value)
    start.setDate(new Date(times.value).getDate())
    start.setHours(0, 0, 0, 0)
    const end = new Date(times.value)
    end.setDate(new Date(times.value).getDate())
    end.setHours(23, 59, 59, 999)
    params.start = formatTime(start)
    params.end = formatTime(end)
    isTodayOrYesterday.value = true
    currentDate.value = new Date(formatTime(start))
    getLotteryList()
}

const yesterday = () => {
    tdas.value = 2
    const start = new Date(times.value)
    start.setDate(new Date(times.value).getDate() - 1)
    start.setHours(0, 0, 0, 0)
    const end = new Date(times.value)
    end.setDate(new Date(times.value).getDate() - 1)
    end.setHours(23, 59, 59, 999)
    params.start = formatTime(start)
    params.end = formatTime(end)
    isTodayOrYesterday.value = true
    getLotteryList()
}

const thisWeek = () => {
    tdas.value = 3
    const start = new Date(times.value)
    let day = start.getDay()
    day = day ? day : 7
    start.setDate(new Date(times.value).getDate() + 1 - day)
    start.setHours(0, 0, 0, 0)
    params.start = formatTime(start)
    params.end = formatTime(new Date(times.value))
    isTodayOrYesterday.value = false
    getLotteryList()
}

const prevWeek = () => {
    tdas.value = 4
    const start = new Date(times.value)
    let prev = start.getDay()
    prev = prev ? prev : 7
    start.setDate(new Date(times.value).getDate() + 1 - prev - 7)
    start.setHours(0, 0, 0, 0)
    const end = new Date(times.value)
    let next = end.getDay()
    next = next ? next : 7
    end.setDate(new Date(times.value).getDate() - next)
    end.setHours(23, 59, 59, 999)
    params.start = formatTime(start)
    params.end = formatTime(end)
    isTodayOrYesterday.value = false
    getLotteryList()
}

const thisMonth = () => {
    tdas.value = 5
    const start = new Date(times.value)
    start.setDate(1)
    start.setHours(0, 0, 0, 0)
    params.start = formatTime(start)
    params.end = formatTime(new Date(times.value))
    isTodayOrYesterday.value = false
    getLotteryList()
}

const prevMonth = () => {
    tdas.value = 6
    // 假设 $time 全局挂载，如果未定义需要实现对应函数
    params.start = window.$time?.prevMonth(times.value) || ''
    params.end = window.$time?.prevMonthEnd(times.value) || ''
    isTodayOrYesterday.value = false
    getLotteryList()
}

const getLotteryList = async() => {
    if (params.lotteryList.length === 1 && isTodayOrYesterday.value && params.lotteryList[0] !== 0) {
        const lot_name = gameTypeList.value.filter(item => params.lotteryList[0] === item.id)[0]?.name
        try {
            const res = await userStore.getperiods(params.lotteryList[0], params.end)
            lotteryList.value = res.data
            options.value = res.data.map(item => {
              return { issue: item, name: `${lotName}-${item}期` }
            })
        } catch (error) {
        console.error('获取期数失败:', error)
        } finally {
        showLoad.value = false
        }
    } else {
        params.period = ''
    }
}

const getGameTypeList = async() => {
    try {
        const res = await userStore.getlotteryAll()
        gameTypeList.value = res.data.map((item: any) => ({
        ...item,
        selected: true
        }))
        params.lotteryList = gameTypeList.value.map(item => item.id)
        if (params.lotteryList.length === 1) {
           getLotteryList()
        }
    } catch (error) {
        console.error('获取游戏类型失败:', error)
        loading.value = false
    }
}

const selectAll = () => {
    yxtp.value = 1
    params.lotteryList = gameTypeList.value.map(item => item.id)
}

const cancelAll = () => {
    yxtp.value = 2
    params.lotteryList = []
}

const reportQuery = () => {
    if (params.lotteryList.length === 0) {
        Toast({ type: 'fail', message: '请选择彩票种类' })
        return
    }
    let tps = {
        start: '',
        end: '',
        accountId: params.accountId,
        lotteryList: params.lotteryList,
        type: params.type,
        status: params.status,
        account: params.account,
        credit: params.credit,
        win: params.win,
        period: params.period,
        playCountType: params.playCountType,
        isacout: params.account ? 1 : 2
    }
    tps.start = params.start + ' 07:00:00'
    let dats = new Date(params.end)
    dats.setDate(dats.getDate() + 1)
    let tt = formatTime(dats)
    tps.end = tt + ' 06:59:59'
    localStorage.setItem('agreportForm',JSON.stringify(tps));
    router.push({ path: 'ReportList'})
}

// --- 生命周期 ---
onMounted(() => {
    getRunDate()
    getGameTypeList()
    window.scrollTo({ top: 0, behavior: 'smooth' })
})
</script>

